@@ -0,0 +1,12 @@
+import { createEventCard } from "./event-card.js";
+
+export function sortChronologically(events, build) {
+  return events
+    .map((event) => ({ result: build(event), time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time)
+    .map((entry) => entry.result);
+}
+
+export function buildAgenda(events) {
+  return sortChronologically(events, createEventCard);
+}

